function whr(waist, hip, gender){ waist=+waist; hip=+hip; gender=String(gender||'male').toLowerCase();
  if(!(waist>0)||!(hip>0)) return {error:'腰围与臀围须为正'};
  var ratio=Math.round(waist/hip*100)/100;
  var high = (gender==='female') ? ratio>=0.85 : ratio>=0.90;
  return {ratio:ratio, level: high?'偏高（中心性肥胖）':'正常', gender:gender}; }
var EXPORTS={whr:whr};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.WhrForgePure = EXPORTS; }
